function viewReport(n){function t(n){if($.unblockUI(),n.success){$("#employee1").val(n.data.applicationUser.fullname);$("#subject1").val(n.data.subject);$("#sender1").val(n.data.sender);$("#message1").val(n.data.message);$("#cash").val(n.data.cost);var t=new Date(n.data.createdDate).getHours();let i=t>=12?"pm":"am",r=n.data.createdDate.toLocaleString("YYYY-MM-dd").slice(0,19).replace("T"," ")+" "+i;$("#createdate1").val(r);$("#paymentmodal").modal("show")}else $.unblockUI(),swal.fire("Ooop!","An error occured while generating the report","error")}function i(){$("#smsloader"+n).hide();$("#nosmsloader"+n).show();$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity!"})}$.ajax({type:"POST",url:"/webapi/SmsDetails/",data:{id:n},dataType:"json",success:t,error:i,beforeSend:function(){blockcallback();$("#smsloader"+n).show();$("#nosmsloader"+n).hide()},complete:function(){$.unblockUI();$("#smsloader"+n).hide();$("#nosmsloader"+n).show()}})}function test(){$("#paymentmodal").modal("hide")}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div> ',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}var dataTable;$(document).ready(function(){dataTable=$("#subjectTable").DataTable({processing:!0,serverSide:!0,filter:!0,ajax:{url:"/Home/LoadSmsData",type:"POST",datatype:"json"},columnDefs:[{targets:[0],visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:null,render:function(n){return n.applicationUser.fullname}},{data:"sender",autoWidth:!0},{data:"subject",autoWidth:!0},{data:"message",render:function(n){return n.length>30?n.substring(0,25)+".....":n}},{data:"cost",autoWidth:!0},{data:"createdDate",autoWidth:!0,render:function(n){var t=new Date(n).getHours();let i=t>=12?"pm":"am";return n.toLocaleString("YYYY-MM-dd").slice(0,19).replace("T"," ")+" "+i}},{data:"id",render:function(n){return`
                        <div class="text-center">
                            <button type="button" class="btn btn-success btn-sm" onclick="return viewReport(${n});" id="buttonsms"  data-id="${n}" style="cursor:pointer">
                            <i class="fa fa-spin fa-spinner" id="smsloader${n}" style="display:none;"></i>
                                <i class="fa fa-eye"  id="nosmsloader${n}"></i>
                            </button>
                        </div>
                    `}}]})});